// WSK-46 (owner ruling WSK-D52) — the draft-preview token: format, hashing and the CORS rule, in ONE
// place that both halves import (the control plane mints, the delivery route reads), so they cannot
// drift apart.
//
// THE TOKEN IS A BEARER CAPABILITY. 32 random bytes from the OS CSPRNG, base64url (43 characters, no
// padding), generated by the api and shown exactly once. Only sha256(token) as lowercase hex is stored
// (migration 0013, preview_tokens.token_hash). There is no pepper: the input has 256 bits of entropy,
// so a keyed hash adds nothing, and an unkeyed one lets the public route look a row up with no secret
// configuration. Nothing here ever compares plaintext: the route hashes what it was given and asks the
// unique index for that hash, so a lookup's timing depends on the hash of the attacker's guess, which
// reveals nothing about any stored token.
import { createHash, randomBytes } from "node:crypto";

/** The mint's default and maximum lifetimes (seconds). */
export const PREVIEW_TTL_DEFAULT_SECONDS = 3600;
export const PREVIEW_TTL_MAX_SECONDS = 86_400;

/** Exactly what mintPreviewToken() produces: 32 bytes as unpadded base64url. */
export const PREVIEW_TOKEN_RE = /^[A-Za-z0-9_-]{43}$/;

/** A fresh token: 32 random bytes, base64url. The plaintext leaves the api once, in the mint response. */
export function mintPreviewToken(): string {
  return randomBytes(32).toString("base64url");
}

/** sha256(token), lowercase hex: what preview_tokens.token_hash holds and what the public route looks up. */
export function hashPreviewToken(token: string): string {
  return createHash("sha256").update(token, "utf8").digest("hex");
}

/**
 * The CORS rule of the public preview route (WSK-46). The response may be read by script only from the
 * site the token belongs to: the request's Origin is echoed ONLY when it is exactly `https://<domain>`
 * for the `environments.domain` of an environment of the token's site (staging or production). The host
 * is compared case-insensitively (browsers lower-case it anyway); the scheme must be https; a port, a
 * path, a trailing slash, a suffix or a sibling subdomain does not match. Returns the Origin string to
 * echo, or null (no CORS header at all).
 */
export function allowedPreviewOrigin(origin: string | null | undefined, domains: readonly string[]): string | null {
  if (!origin) return null;
  const wanted = origin.toLowerCase();
  for (const raw of domains) {
    const domain = raw.trim().toLowerCase();
    // a stored value that is not a bare host[:port] (a scheme, a path, whitespace, userinfo...) never matches
    if (domain === "" || /[\/\s@?#\\]/.test(domain)) continue;
    if (wanted === `https://${domain}`) return origin;
  }
  return null;
}

/**
 * The path with a preview token replaced by `:token`. For log lines and problem `instance` members:
 * a capability must not be copied into logs or error bodies that outlive the request.
 */
export function redactPreviewToken(path: string): string {
  // ["", "v1", "t", <slug>, "preview", <token>, ...]. The fourth segment is compared DECODED, as the router
  // does, so `%70review` is redacted too.
  const parts = path.split("/");
  if (parts.length < 6 || parts[1] !== "v1" || parts[2] !== "t") return path;
  let segment: string;
  try {
    segment = decodeURIComponent(parts[4]);
  } catch {
    return path;
  }
  if (segment.toLowerCase() !== "preview") return path;
  parts[5] = ":token";
  return parts.join("/");
}
